import bisect

def longest_increasing_subsequence(a):
    n = len(a)
    if n == 0:
        return []

    # This will store the smallest tail of all increasing subsequences with different lengths
    lis = []
    # This will store the index of the previous element in the LIS
    prev_index = [-1] * n
    # This will store the count of LIS ending at each element
    count = [1] * n
    # This will store the total number of LIS
    total_lis_count = 0

    for i in range(n):
        pos = bisect.bisect_left(lis, a[i])
        if pos == len(lis):
            lis.append(a[i])
        else:
            lis[pos] = a[i]

        if pos > 0:
            count[i] = count[prev_index[pos - 1]]

        if pos == len(lis) - 1:
            total_lis_count += count[i]
            if pos > 0:
                count[i] += count[prev_index[pos - 1]]

        if pos > 0:
            prev_index[i] = prev_index[pos - 1]

    result = ['0'] * n
    for i in range(n - 1, -1, -1):
        if lis[-1] == a[i]:
            if count[i] == total_lis_count:
                result[i] = '3'
            elif count[i] > 0:
                result[i] = '2'
            else:
                result[i] = '1'
            lis.pop()
            total_lis_count -= count[i]

    return ''.join(result)

